import * as stylex from '@stylexjs/stylex';
const w = '5px';
export const styles = stylex.create({ a: (w) => ({ width: w }) });

import * as stylex from '@stylexjs/stylex';
const h = '5px';
export const styles = stylex.create({ a: (w) => ({ width: w, height: h }) });

import * as stylex from '@stylexjs/stylex';
const base = { color: 'red' };
export const styles = stylex.create({ a: (w) => ({ ...base, width: w }) });
